INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e1040000-0000-4000-8000-000000000007', 'e1030000-0000-4000-8000-000000000003', 1, 'TEXT', 'Mỗi từ để hỏi tìm một loại thông tin: Who là người, When là thời gian, Where là nơi chốn, What là vật hoặc việc. Gạch chân từ để hỏi, rồi tìm trong đoạn từ cùng loại: tên riêng cho Who, giờ hoặc ngày cho When, địa danh cho Where.');
