INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e1040000-0000-4000-8000-000000000028', 'e1030000-0000-4000-8000-000000000010', 1, 'TEXT', 'Câu hỏi hiện tại dùng do/does: "Do you like tea?", "Does she work here?". Phủ định dùng don''t/doesn''t + động từ nguyên mẫu: "He doesn''t like tea". Với be, đảo vị trí: "Is he tired?", "He isn''t tired". Từ để hỏi (what, where, when) đứng đầu câu.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('e1040000-0000-4000-8000-000000000028', (SELECT id FROM knowledge_points WHERE code = 'G40_QUESTIONS_NEGATIVES'));
