INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('e1070000-0000-4000-8000-000000000072', 'e1060000-0000-4000-8000-000000000072', 1, 'Choose the correct sentence.', '[{"optionKey": "A", "content": "He doesn''t like fish.", "sortOrder": 1}, {"optionKey": "B", "content": "He don''t like fish.", "sortOrder": 2}, {"optionKey": "C", "content": "He doesn''t likes fish.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'After doesn''t the verb stays in the base form.', 'EASY', 'PUBLISHED');
