INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e1040000-0000-4000-8000-000000000030', 'e1030000-0000-4000-8000-000000000011', 1, 'TEXT', 'Quá khứ đơn kể việc đã xong. Động từ có quy tắc thêm -ed (walk → walked); động từ bất quy tắc thường gặp phải nhớ: go → went, have → had, see → saw, buy → bought. Phủ định và câu hỏi dùng did + nguyên mẫu: "I didn''t go", "Did you go?".');
