INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e1040000-0000-4000-8000-000000000032', 'e1030000-0000-4000-8000-000000000012', 1, 'TEXT', 'Một tin nhắn ngắn có ba phần: lời chào ("Hi Sam,"), nội dung (một đến ba câu: mục đích, thời gian, nơi chốn) và lời kết ("See you on Friday!"). Dùng câu đơn giản, đúng thì: kể việc đã xảy ra bằng quá khứ đơn, đề nghị bằng "Can we...?" hoặc "Shall we...?".');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('e1040000-0000-4000-8000-000000000032', (SELECT id FROM knowledge_points WHERE code = 'W40_SHORT_MESSAGE'));
