INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('e1070000-0000-4000-8000-000000000087', (SELECT id FROM knowledge_points WHERE code = 'W40_SHORT_MESSAGE'), 1.0);
